mapper.delete:
DELETE FROM COLLECTION_LIKE
 WHERE MEMBER_ID     = #{memberId}
   AND COLLECTION_ID = #{collectionId}

mapper.select:
SELECT MEMBER_ID,
       COLLECTION_ID,
       TO_CHAR(CREATED_DT, 'YYYY-MM-DD HH24:MI:SS') AS CREATED_DT
  FROM COLLECTION_LIKE
 WHERE MEMBER_ID     = #{memberId}
   AND COLLECTION_ID = #{collectionId}

SELECT COUNT(*)
  FROM COLLECTION_LIKE cl
  JOIN COLLECTION c
    ON cl.COLLECTION_ID = c.COLLECTION_ID
 WHERE cl.MEMBER_ID = #{memberId}
   AND (
        c.IS_PUBLIC = 'Y'
        OR c.MEMBER_ID = #{currentMemberId,jdbcType=NUMERIC}
   )

SELECT COUNT(*)
  FROM COLLECTION_LIKE
 WHERE COLLECTION_ID = #{collectionId}
